"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  APPEAL_SHARES,
  BURDEN_ASYMMETRY,
  HEADLINE,
  HHI_BANDS,
  INCOME_SHARES,
  LENS_COMPARE,
  PLAN_LEVERAGE,
  ROLE_SCATTER,
  SOURCE_NOTE,
  curveForLens,
  fmtBn,
  fmtHhi,
  fmtM,
  fmtPct,
  hhiBand,
  sharesForLens,
  type LensId,
} from "@/data/migration-humanitarian-concentration-2026-data";

// viz-types: Lens ladder bars, Lorenz area+line, burden asymmetry bars, HHI donut, plan leverage scatter, host-donor role scatter | layout: default

type ViewId = "ladder" | "curve" | "burden" | "leverage";
type Metric = "top1" | "top3" | "hhi";

const SKY = "#0ea5e9";
const ROSE = "#f43f5e";
const AMBER = "#f59e0b";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function MigrationHumanitarianConcentration2026Dashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [metric, setMetric] = useState<Metric>("top3");
  const [lens, setLens] = useState<LensId>("donors");
