    [],
  );

  const roleScatter = useMemo(
    () =>
      ROLE_SCATTER.map((r) => ({
        ...r,
        x: r.hostedM,
        y: r.donorSharePct,
        z: Math.max(70, (r.hostedM + 0.5) * 40 + r.donorSharePct * 2),
