const failed = [];
page.on("response", (r) => {
  if (r.status() >= 400) failed.push(`${r.status()} ${r.url()}`);
});
page.on("pageerror", (e) => console.log("PAGEERROR", e.message));
await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
  waitUntil: "networkidle",
  timeout: 60000,
});
await page.waitForTimeout(5000);
console.log("data-viz count", await page.locator("[data-viz]").count());
console.log(
  "loading count",
  await page.getByText("Loading interactive charts").count(),
);
console.log("failed", failed.slice(0, 20));
const html = await page.content();
console.log("has marker text", /Migration &.? humanitarian ??? concentration lens/.test(html));
console.log("has data-viz", html.includes(`data-viz="${slug}"`));
await browser.close();
await stopStaticServer(server);

